import { readFile, writeFile } from 'node:fs/promises'

const [manifestPath] = process.argv.slice(2)
const manifest = JSON.parse(await readFile(manifestPath, 'utf8'))
const flags = [...new Set(manifest.configureFlags)]
const output = [
  '# Generated by build/write-codec-flags.mjs. Do not edit.',
  'CODEC_FLAGS=(',
  ...flags.map((flag) => `  ${JSON.stringify(flag)}`),
  ')',
  ''
].join('\n')

await writeFile(new URL('./codec-flags.sh', import.meta.url), output)
